(101, 'DT101', 'Xây dựng nền tảng quản lý thực tập và kết nối doanh nghiệp', 'Phát triển cổng đăng ký thực tập, quản lý vị trí tuyển dụng, theo dõi tiến độ và đánh giá của doanh nghiệp dành cho sinh viên.', 'Java Spring Boot, MySQL, thiết kế REST API và phân quyền người dùng.', 1, 1, 1, NULL, 3, 'PUBLISHED', '2026-09-10 08:00:00', '2026-10-18 09:00:00'),
(102, 'DT102', 'Bảo vệ dữ liệu cá nhân trong giao dịch thương mại điện tử', 'Phân tích quy định bảo vệ dữ liệu cá nhân, khảo sát quy trình thu thập dữ liệu trên sàn thương mại điện tử và đề xuất giải pháp tuân thủ.', 'Kiến thức pháp luật dân sự, thương mại điện tử và phương pháp nghiên cứu tình huống.', 2, 1, 7, NULL, 3, 'PUBLISHED', '2026-09-11 08:00:00', '2026-10-18 10:00:00'),
(103, 'DT103', 'Ứng dụng BIM trong lập kế hoạch và kiểm soát tiến độ thi công', 'Xây dựng mô hình BIM cho công trình dân dụng, liên kết tiến độ thi công và đề xuất quy trình giám sát khối lượng thực hiện.', 'Sử dụng Revit, kiến thức quản lý xây dựng và lập tiến độ công trình.', 3, 1, 8, NULL, 3, 'PUBLISHED', '2026-09-12 08:00:00', '2026-10-18 11:00:00'),
(104, 'DT104', 'Thiết kế hệ thống giám sát điện năng cho phòng học thông minh', 'Thiết kế thiết bị đo điện năng, truyền dữ liệu qua mạng và xây dựng bảng điều khiển cảnh báo tiêu thụ điện bất thường.', 'Vi điều khiển ESP32, cảm biến đo điện năng, MQTT và lập trình hệ thống nhúng.', 4, 1, 9, NULL, 3, 'PUBLISHED', '2026-09-13 08:00:00', '2026-10-18 14:00:00'),
(105, 'DT105', 'Thiết kế và tối ưu cơ cấu phân loại sản phẩm trên băng tải', 'Mô hình hóa cơ cấu phân loại, tính toán truyền động, chế tạo mô hình thử nghiệm và đánh giá năng suất hoạt động.', 'Thiết kế cơ khí với SolidWorks, tính toán truyền động và kiến thức điều khiển tự động.', 5, 21, 10, NULL, 3, 'PUBLISHED', '2026-10-10 08:00:00', '2026-10-19 09:00:00'),
(106, 'DT106', 'Phân tích dữ liệu bán hàng và dự báo nhu cầu cho cửa hàng bán lẻ', 'Thu thập dữ liệu bán hàng mẫu, phân tích xu hướng tiêu dùng, xây dựng mô hình dự báo nhu cầu và đề xuất kế hoạch tồn kho.', 'Thống kê kinh doanh, xử lý dữ liệu bằng Python và trực quan hóa bằng Power BI.', 6, 21, 11, NULL, 3, 'PUBLISHED', '2026-10-12 08:00:00', '2026-10-19 10:00:00'),
(107, 'DT107', 'Ứng dụng nhận dạng văn bản trong số hóa hồ sơ sinh viên', 'Xây dựng ứng dụng trích xuất thông tin từ biểu mẫu, kiểm tra dữ liệu nhận dạng và lưu trữ hồ sơ có khả năng tìm kiếm.', 'Python, xử lý ảnh, OCR và xây dựng giao diện web.', 1, 22, 2, NULL, 3, 'PUBLISHED', '2026-10-12 08:00:00', '2026-10-20 09:00:00'),
(108, 'DT108', 'Xây dựng hệ thống đặt lịch sử dụng phòng thực hành', 'Phát triển chức năng tra cứu phòng trống, đăng ký lịch, duyệt yêu cầu và phát hiện lịch sử dụng phòng bị trùng.', 'Java Spring Boot, MySQL, kiểm thử phần mềm và thiết kế giao diện web.', 1, 22, 5, NULL, 3, 'PUBLISHED', '2026-10-14 08:00:00', '2026-10-20 10:00:00');
